const cmd=`python3 -c "import json
from pathlib import Path
root=Path('local_soul_eval')
runs={
'deepseek':root/'outputs/deepseek_deepseek-v4-flash-0731_41499227',
'nemotron':root/'outputs/nvidia_nemotron-3-ultra-550b-a55b_free_41548025',
'ox_alpha':root/'outputs/stealth_ox-alpha_41548043',
}
out={}
for name,path in runs.items():
    summary=json.loads((path/'summary.json').read_text()) if (path/'summary.json').exists() else None
    results=sum(1 for _ in (path/'results.jsonl').open()) if (path/'results.jsonl').exists() else 0
    errors=sum(1 for _ in (path/'errors.jsonl').open()) if (path/'errors.jsonl').exists() else 0
    samples=[]
    if (path/'errors.jsonl').exists():
        lines=(path/'errors.jsonl').read_text().splitlines()
        for line in lines[-3:]:
            row=json.loads(line)
            samples.append({'task':row.get('task'),'index':row.get('index'),'error_type':row.get('error_type'),'error':str(row.get('error'))[:1200]})
    out[name]={'summary':summary,'result_lines':results,'error_lines':errors,'last_errors':samples}
for name,job in [('deepseek','soul-dsv4f-41499227'),('nemotron','soul-nemo-free-41548025'),('ox_alpha','soul-ox-free-41548043')]:
    for ext in ('out','err'):
        p=root/'logs'/f'{job}.{ext}'
        out[name][f'slurm_{ext}_tail']='\\n'.join(p.read_text().splitlines()[-20:]) if p.exists() else None
print(json.dumps(out,indent=2))"`;
